{
  "command": "cd /mnt/session/uploads && ls -la app.log && grep -c 'db_query sql="SELECT \* FROM order_items WHERE order_id = ?"' app.log; grep -m3 'db_query' app.log; grep -o 'db_query[^]]*' app.log | head -0; python3 - <<'EOF'
import re,collections
c=collections.Counter()
pat=re.compile(r'(\d{4}-\d\d-\d\dT\d\d:\d\d)')
with open('app.log',errors='ignore') as f:
    for line in f:
        if 'order_items WHERE order_id = ?' in line:
            m=pat.search(line)
            if m: c[m.group(1)]+=1
for k in sorted(c): print(k,c[k])
EOF"
}
